from pathlib import Path
from html.parser import HTMLParser
from hashlib import sha256
import json
import re

class PageText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.hidden = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if tag in ('script', 'style', 'template'):
            self.hidden += 1

    def handle_endtag(self, tag):
        if tag in ('script', 'style', 'template') and self.hidden:
            self.hidden -= 1

    def handle_data(self, value):
        if not self.hidden:
            self.parts.append(value)

root = Path('products/services/sqlite-lemon-squeezy-payout-evidence')
raw = (root / 'raw/store-activation.html').read_bytes()
digest = sha256(raw).hexdigest()
assert digest == '70076f16e4074dad57d7fbc818935ef4a7b891e85227112ccff51a6f3ec2e308', digest
page = PageText()
page.feed(raw.decode('utf-8'))
text = ' '.join(' '.join(page.parts).split())
topics = {'identity': r'identity verification|verify your identity|government.issued', 'review': r'under review|review your|approve your|approval process|manually review', 'activation': r'activation request|activate your store|live mode', 'product': r'prohibited products|what you (?:plan|intend) to sell|what you sell|products you|product eligibility'}
excerpts = {}
for topic, pattern in topics.items():
    matches = re.finditer(pattern, text, re.IGNORECASE)
    excerpts[topic] = list(dict.fromkeys(text[max(0, match.start()-75):match.end()+125] for match in matches))[:6]
result = {'source': 'https://docs.lemonsqueezy.com/help/getting-started/activate-your-store', 'source_sha256': digest, 'source_receipt': 'TASK-179546041801', 'method': 'Visible HTML text rendered as whitespace-normalized excerpts for manual review. An empty result does not establish absence of a requirement.', 'excerpts': excerpts, 'affected_operation': 'Store activation and live checkout for the intended seller', 'evidence_needed': 'Applicable first-party activation terms and recorded seller approval. Resolve any package-specific eligibility uncertainty against first-party product terms or a platform decision.'}
out = root / 'director-store-activation-evidence.json'
out.write_text(json.dumps(result, indent=2, ensure_ascii=False) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(out), 'matches_by_topic': {topic: len(matches) for topic, matches in excerpts.items()}}))
